window.kbPageData["views/entry/k-2661966960e6001a"] = {"key":"entry/k-2661966960e6001a","state":{"route":"entry/k-2661966960e6001a"},"node":{"id":"k-2661966960e6001a","mode":"k","title":"热极生风（气象谚语）","type":"概念与词义","domain":"汉语","reading":"","intro":"","priority":100,"aliases":["热极生风指天气过热后起风"],"qs":["江苏 2025 A类 行测#73"],"current":false,"candidates":true,"sources":[],"basisGroup":"","authority":null,"sourceOnly":false,"reviewSet":"单次条目","independentCount":1,"repeatPositions":0,"directorySummary":"气象谚语，指天气很热时容易起风，是对天气现象的民间经验概括。","review":{"definition":"气象谚语，指天气很热时容易起风，是对天气现象的民间经验概括。","explanation":"《白河县志》将这句话列入气象谚语。题中“热极”表示炎热达到很高程度，“生风”表示随之出现的变化，与“穷极”引出“思变”构成平行关系。谚语表达的是经验性倾向，遇到高温时是否起风还取决于具体气象条件。","references":[{"source":"web-dcbb182dc398869e","location":"第六节“物候”附录“气象谚语”","quote":"热极生风，闷极生雨。"}],"evidence":"因为“热极”所以“生风”，因为“穷极”所以“思变”","disposition":"独立词条","basis":"据原题与所列资料编释。"}},"questions":{"江苏 2025 A类 行测#73":{"paper":"江苏 2025 A类 行测","n":73,"mod":"判断推理","src":["98687766ac277f427cd6.pdf",14],"asrc":["4fe8e0544dd7b47699d2.pdf",23],"card":"eced3ce8a50d70f2e13e5ccd","links":[{"id":"k-2661966960e6001a","role":"解题依据","why":"该短语的释义给出极端状态及其引发的自然变化。"}]}},"terms":{},"references":{"web-dcbb182dc398869e":{"name":"白河县地方志编纂委员会《白河县志》","url":"https://dfz.shaanxi.gov.cn/zslm/fzzlk/xbsxsxz/xbsxz/aks_16206/201405/P020240923608857915828.pdf"}},"topics":[],"units":{"k-2661966960e6001a":[["江苏 2025 A类 行测#73"]]}};
